// Versión «gorda»: un solo manejador hace todo. Datos inventados, todo en memoria.
const express = require('express');

function crearApp() {
  const despachos = new Map([
    [1, { id: 1, cliente: 'Ferretería Norte', bultos: 12, estado: 'nuevo', patente: null }],
    [2, { id: 2, cliente: 'Kiosco Sur', bultos: 10, estado: 'nuevo', patente: null }],
    [3, { id: 3, cliente: 'Taller Oeste', bultos: 5, estado: 'entregado', patente: 'AA111AA' }],
    [4, { id: 4, cliente: 'Librería Este', bultos: 15, estado: 'asignado', patente: 'AA111AA' }],
    [5, { id: 5, cliente: 'Panadería Centro', bultos: 5, estado: 'nuevo', patente: null }],
  ]);
  const vehiculos = new Map([
    ['AA111AA', { patente: 'AA111AA', capacidad: 20 }],
    ['BB222BB', { patente: 'BB222BB', capacidad: 8 }],
  ]);
  const avisos = [];

  const app = express();
  app.locals.avisos = avisos;
  app.use(express.json());

  app.post('/despachos/:id/asignar', (req, res) => {
    const id = Number(req.params.id);
    const patente = req.body?.patente;
    if (!Number.isInteger(id) || typeof patente !== 'string')
      return res.status(400).json({ error: 'faltan datos' });

    const d = despachos.get(id);
    if (!d) return res.status(404).json({ error: 'no existe ese despacho' });
    const v = vehiculos.get(patente);
    if (!v) return res.status(404).json({ error: 'no existe ese vehículo' });

    if (d.estado !== 'nuevo') return res.status(409).json({ error: 'el despacho ya no está nuevo' });
    let cargado = 0;
    for (const otro of despachos.values())
      if (otro.patente === v.patente && otro.estado !== 'entregado') cargado += otro.bultos;
    if (cargado + d.bultos > v.capacidad)
      return res.status(409).json({ error: `no entra: lleva ${cargado} de ${v.capacidad} bultos` });

    d.estado = 'asignado';
    d.patente = v.patente;
    avisos.push(`aviso a ${d.cliente}: su despacho ${d.id} sale en ${v.patente}`);
    res.json(d);
  });

  return app;
}

module.exports = { crearApp };

// Pruebas de «caracterización»: fijan lo que el endpoint hace hoy, sin mirar cómo está hecho por dentro.
const test = require('node:test');
const assert = require('node:assert/strict');
const { crearApp } = require(process.env.IMPL);

let app, servidor, base;
test.beforeEach(async () => {
  app = crearApp();
  servidor = app.listen(0, '127.0.0.1');
  await new Promise((ok) => servidor.once('listening', ok));
  base = `http://127.0.0.1:${servidor.address().port}`;
});
test.afterEach(() => servidor.close());

const asignar = (id, cuerpo) =>
  fetch(`${base}/despachos/${id}/asignar`, {
    method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(cuerpo),
  });

test('asigna cuando entra justo en el vehículo (15 + 5 = 20)', async () => {
  const r = await asignar(5, { patente: 'AA111AA' });
  assert.equal(r.status, 200);
  assert.deepEqual(await r.json(), { id: 5, cliente: 'Panadería Centro', bultos: 5, estado: 'asignado', patente: 'AA111AA' });
});
