  assert.equal(app.locals.avisos.length, 0);
  await asignar(5, { patente: 'AA111AA' });   // aceptada
  assert.deepEqual(app.locals.avisos, ['aviso a Panadería Centro: su despacho 5 sale en AA111AA']);
