// Capa de datos: sabe DÓNDE se guardan las cosas (acá, en memoria). No sabe de reglas ni de HTTP.
function crearRepositorio({ despachos, vehiculos }) {
  const d = new Map(despachos.map((x) => [x.id, { ...x }]));
  const v = new Map(vehiculos.map((x) => [x.patente, { ...x }]));
  return {
    buscarDespacho: (id) => (d.has(id) ? { ...d.get(id) } : null),
    buscarVehiculo: (patente) => (v.has(patente) ? { ...v.get(patente) } : null),
    bultosCargados: (patente) =>
      [...d.values()].filter((x) => x.patente === patente && x.estado !== 'entregado')
        .reduce((suma, x) => suma + x.bultos, 0),
    guardarDespacho: (x) => { d.set(x.id, { ...x }); },
  };
}
module.exports = { crearRepositorio };

// Capa de servicio: sabe las REGLAS (qué se puede asignar y qué no). No sabe de HTTP ni de dónde están los datos.
const { ErrorDeNegocio } = require('./errores');

function crearServicio({ repo, avisar }) {
  return {
    asignar(idDespacho, patente) {
      const despacho = repo.buscarDespacho(idDespacho);
      if (!despacho) throw new ErrorDeNegocio('despacho_inexistente', 'no existe ese despacho');
      const vehiculo = repo.buscarVehiculo(patente);
      if (!vehiculo) throw new ErrorDeNegocio('vehiculo_inexistente', 'no existe ese vehículo');

      if (despacho.estado !== 'nuevo')
        throw new ErrorDeNegocio('despacho_no_nuevo', 'el despacho ya no está nuevo');
      const cargado = repo.bultosCargados(patente);
      if (cargado + despacho.bultos > vehiculo.capacidad)
        throw new ErrorDeNegocio('no_entra', `no entra: lleva ${cargado} de ${vehiculo.capacidad} bultos`);

      const asignado = { ...despacho, estado: 'asignado', patente };
      repo.guardarDespacho(asignado);
      avisar(`aviso a ${asignado.cliente}: su despacho ${asignado.id} sale en ${patente}`);
      return asignado;
    },
  };
}
module.exports = { crearServicio };

// Controlador: sabe de HTTP. Traduce el pedido a una llamada al servicio y el resultado a una respuesta.
const { ErrorDeNegocio } = require('./errores');

const ESTADO_HTTP = {
  despacho_inexistente: 404,
  vehiculo_inexistente: 404,
  despacho_no_nuevo: 409,
  no_entra: 409,
};

function crearControlador(servicio) {
  return {
    asignar(req, res, next) {
      const id = Number(req.params.id);
      const patente = req.body?.patente;
      if (!Number.isInteger(id) || typeof patente !== 'string')
        return res.status(400).json({ error: 'faltan datos' });
      try {
        res.json(servicio.asignar(id, patente));
      } catch (e) {
        if (e instanceof ErrorDeNegocio)
          return res.status(ESTADO_HTTP[e.codigo] ?? 500).json({ error: e.message });
        next(e);                      // lo inesperado le toca al manejador de errores
      }
    },
  };
}
module.exports = { crearControlador };

