function crearAppCon(crearRepo) {
  const avisos = [];
  const servicio = crearServicio({ repo: crearRepo(SEMILLA), avisar: (texto) => avisos.push(texto) });
  const controlador = crearControlador(servicio);

  const app = express();
  app.locals.avisos = avisos;
  app.use(express.json());
  app.post('/despachos/:id/asignar', controlador.asignar);
  return app;
}

module.exports = { crearAppCon, crearApp: () => crearAppCon(crearRepositorio) };

// Pruebas del servicio SOLO: sin Express, sin HTTP, sin puertos.
const test = require('node:test');
const assert = require('node:assert/strict');
const { SEMILLA } = require('./capas/datos');
const { crearRepositorio } = require('./capas/repositorio');
const { crearRepositorioSqlite } = require('./capas/repositorio-sqlite');
const { crearServicio } = require('./capas/servicio');

for (const [nombre, crearRepo] of [['memoria', crearRepositorio], ['sqlite', crearRepositorioSqlite]]) {
  const armar = () => {
    const avisos = [];
    return { avisos, servicio: crearServicio({ repo: crearRepo(SEMILLA), avisar: (t) => avisos.push(t) }) };
  };

  test(`[${nombre}] entra justo: 15 + 5 = 20`, () => {
    const { servicio, avisos } = armar();
    assert.equal(servicio.asignar(5, 'AA111AA').estado, 'asignado');
    assert.equal(avisos.length, 1);
  });
  test(`[${nombre}] se pasa por un bulto: error no_entra y sin aviso`, () => {
    const { servicio, avisos } = armar();
    assert.throws(() => servicio.asignar(1, 'AA111AA'), { codigo: 'no_entra', message: /lleva 15 de 20/ });
    assert.equal(avisos.length, 0);
  });
  test(`[${nombre}] despacho que no existe`, () => {
    assert.throws(() => armar().servicio.asignar(99, 'AA111AA'), { codigo: 'despacho_inexistente' });
  });
  test(`[${nombre}] despacho que ya no está nuevo`, () => {
    assert.throws(() => armar().servicio.asignar(4, 'AA111AA'), { codigo: 'despacho_no_nuevo' });
  });
  test(`[${nombre}] en un vehículo de 8 bultos entra el despacho de 5 y no el de 10`, () => {
    const { servicio } = armar();
    assert.equal(servicio.asignar(5, 'BB222BB').patente, 'BB222BB');
    assert.throws(() => servicio.asignar(2, 'BB222BB'), { codigo: 'no_entra' });
  });
}

