// Otro repositorio con la MISMA interfaz, ahora sobre SQLite (módulo node:sqlite de Node 22).
const { DatabaseSync } = require('node:sqlite');

function crearRepositorioSqlite({ despachos, vehiculos }) {
  const db = new DatabaseSync(':memory:');
  db.exec(`create table despachos (id integer primary key, cliente text, bultos integer, estado text, patente text);
           create table vehiculos (patente text primary key, capacidad integer);`);
  const altaD = db.prepare('insert into despachos values (?, ?, ?, ?, ?)');
  for (const x of despachos) altaD.run(x.id, x.cliente, x.bultos, x.estado, x.patente);
  const altaV = db.prepare('insert into vehiculos values (?, ?)');
  for (const x of vehiculos) altaV.run(x.patente, x.capacidad);

  const fila = (r) => (r ? { ...r } : null);
  return {
    buscarDespacho: (id) => fila(db.prepare('select * from despachos where id = ?').get(id)),
    buscarVehiculo: (patente) => fila(db.prepare('select * from vehiculos where patente = ?').get(patente)),
    bultosCargados: (patente) => db.prepare(
      "select coalesce(sum(bultos), 0) as n from despachos where patente = ? and estado <> 'entregado'").get(patente).n,
    guardarDespacho: (x) => {
      db.prepare('update despachos set cliente = ?, bultos = ?, estado = ?, patente = ? where id = ?')
        .run(x.cliente, x.bultos, x.estado, x.patente, x.id);
    },
  };
}
module.exports = { crearRepositorioSqlite };
